{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "FMPEP showed high brain tissue uptake in rats after systemic injection, supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "[11C]MePPEP showed high brain uptake in monkeys by PET, confirming CNS access in a higher species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "[11C]ketamine showed poor brain uptake in animal studies, but this was attributed to rapid metabolism rather than an intrinsic BBB impermeability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most direct in-vivo evidence from structurally related molecules demonstrates high brain uptake after systemic administration across rodents and primates, supporting meaningful CNS access. The single negative record is confounded by rapid metabolism and does not establish barrier failure.",
  "evidence_gaps": [
    "Low Morgan similarity between the query and the evidence molecules limits transferability.",
    "No direct query-specific CNS exposure data are available.",
    "The negative ketamine record is confounded by rapid metabolism rather than being a clear BBB permeability failure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

